// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IERC20
 */
interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

/**
 * @title ICFXToken
 */
interface ICFXToken {
    function mint(address to, uint256 amount) external;
    function burn(address from, uint256 amount) external;
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/**
 * @title IMultiTokenPriceOracle
 */
interface IMultiTokenPriceOracle {
    function getTokenPrice(address token) external view returns (uint256);
}

/**
 * @title PairVaultCloneable
 * @dev Cloneable vault for any two ERC20 tokens - optimized for minimal proxy pattern
 */
contract PairVaultCloneable {
    
    // State variables (not immutable for clones)
    address public token0;
    address public token1;
    address public cfxToken;
    address public priceOracle;
    address public owner;
    address public feeCollector;
    
    uint256 private reserve0;
    uint256 private reserve1;
    uint256 public lastFeeCollection;
    uint256 public depositFee = 10;
    uint256 public withdrawFee = 10;
    uint256 public managementFee = 100;
    
    bool public paused;
    bool private initialized;
    uint8 private locked;
    
    // Constants
    uint256 private constant MIN_LIQUIDITY = 1000;
    uint256 private constant BASIS_POINTS = 10000;
    uint256 private constant RATIO_TOLERANCE = 10;
    
    // Events
    event Deposit(address indexed user, uint256 amount0, uint256 amount1, uint256 cfxMinted);
    event Withdrawal(address indexed user, uint256 cfxBurned, uint256 amount0, uint256 amount1);
    event ManagementFeeCollected(uint256 feeAmount);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }
    
    modifier nonReentrant() {
        require(locked == 1, "Locked");
        locked = 2;
        _;
        locked = 1;
    }
    
    modifier whenNotPaused() {
        require(!paused, "Paused");
        _;
    }
    
    /**
     * @dev Constructor - Only for implementation deployment
     * This won't be called for clones
     */
    constructor() {
        // Lock implementation to prevent initialization
        initialized = true;
    }
    
    /**
     * @dev Initialize function - called once per clone
     * Replaces constructor for clones
     */
    function initialize(
        address _token0,
        address _token1,
        address _cfxToken,
        address _priceOracle,
        address _feeCollector
    ) external {
        require(!initialized, "Already initialized");
        require(_token0 != address(0) && _token1 != address(0), "Invalid tokens");
        require(_token0 != _token1, "Same tokens");
        require(_cfxToken != address(0), "Invalid CFX");
        require(_priceOracle != address(0), "Invalid oracle");
        require(_feeCollector != address(0), "Invalid collector");
        
        token0 = _token0;
        token1 = _token1;
        cfxToken = _cfxToken;
        priceOracle = _priceOracle;
        feeCollector = _feeCollector;
        owner = tx.origin; // Factory caller becomes owner
        lastFeeCollection = block.timestamp;
        locked = 1;
        initialized = true;
    }
    
    /**
     * @dev Add liquidity
     */
    function addLiquidity(
        uint256 amount0,
        uint256 amount1,
        uint256 minCFXOut
    ) external nonReentrant whenNotPaused returns (uint256 cfxMinted) {
        require(amount0 > 0 && amount1 > 0, "Invalid amounts");
        
        _collectManagementFee();
        
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        uint256 cfxToMint;
        
        if (totalCFX == 0) {
            cfxToMint = _sqrt(amount0 * amount1);
            require(cfxToMint > MIN_LIQUIDITY, "Low liquidity");
            cfxToMint -= MIN_LIQUIDITY;
        } else {
            require(reserve0 > 0 && reserve1 > 0, "Invalid reserves");
            
            uint256 required1 = (amount0 * reserve1) / reserve0;
            uint256 diff = required1 > amount1 ? required1 - amount1 : amount1 - required1;
            require(diff * BASIS_POINTS <= required1 * RATIO_TOLERANCE, "Invalid ratio");
            
            uint256 cfx0 = (amount0 * totalCFX) / reserve0;
            uint256 cfx1 = (amount1 * totalCFX) / reserve1;
            cfxToMint = cfx0 < cfx1 ? cfx0 : cfx1;
        }
        
        uint256 fee0 = (amount0 * depositFee) / BASIS_POINTS;
        uint256 fee1 = (amount1 * depositFee) / BASIS_POINTS;
        
        cfxMinted = (cfxToMint * (BASIS_POINTS - depositFee)) / BASIS_POINTS;
        require(cfxMinted >= minCFXOut, "Slippage");
        
        require(IERC20(token0).transferFrom(msg.sender, address(this), amount0), "Transfer failed");
        require(IERC20(token1).transferFrom(msg.sender, address(this), amount1), "Transfer failed");
        
        if (fee0 > 0) IERC20(token0).transfer(feeCollector, fee0);
        if (fee1 > 0) IERC20(token1).transfer(feeCollector, fee1);
        
        reserve0 += amount0 - fee0;
        reserve1 += amount1 - fee1;
        
        ICFXToken(cfxToken).mint(msg.sender, cfxMinted);
        
        emit Deposit(msg.sender, amount0, amount1, cfxMinted);
    }
    
    /**
     * @dev Remove liquidity
     */
    function removeLiquidity(
        uint256 cfxAmount,
        uint256 minAmount0,
        uint256 minAmount1
    ) external nonReentrant returns (uint256 amount0, uint256 amount1) {
        require(cfxAmount > 0, "Invalid CFX");
        require(ICFXToken(cfxToken).balanceOf(msg.sender) >= cfxAmount, "Low balance");
        
        _collectManagementFee();
        
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        require(totalCFX > 0, "No liquidity");
        
        amount0 = (cfxAmount * reserve0) / totalCFX;
        amount1 = (cfxAmount * reserve1) / totalCFX;
        require(amount0 > 0 && amount1 > 0, "Low amounts");
        
        uint256 fee0 = (amount0 * withdrawFee) / BASIS_POINTS;
        uint256 fee1 = (amount1 * withdrawFee) / BASIS_POINTS;
        
        uint256 final0 = amount0 - fee0;
        uint256 final1 = amount1 - fee1;
        
        require(final0 >= minAmount0 && final1 >= minAmount1, "Slippage");
        
        reserve0 -= amount0;
        reserve1 -= amount1;
        
        require(ICFXToken(cfxToken).transferFrom(msg.sender, address(this), cfxAmount), "CFX transfer failed");
        ICFXToken(cfxToken).burn(address(this), cfxAmount);
        
        IERC20(token0).transfer(msg.sender, final0);
        IERC20(token1).transfer(msg.sender, final1);
        
        if (fee0 > 0) IERC20(token0).transfer(feeCollector, fee0);
        if (fee1 > 0) IERC20(token1).transfer(feeCollector, fee1);
        
        emit Withdrawal(msg.sender, cfxAmount, final0, final1);
    }
    
    function _collectManagementFee() internal {
        uint256 elapsed = block.timestamp - lastFeeCollection;
        if (elapsed < 1 days) return;
        
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        if (totalCFX == 0) return;
        
        uint256 feeAmount = (totalCFX * managementFee * elapsed) / (BASIS_POINTS * 365 days);
        
        if (feeAmount > 0) {
            ICFXToken(cfxToken).mint(feeCollector, feeAmount);
            lastFeeCollection = block.timestamp;
            emit ManagementFeeCollected(feeAmount);
        }
    }
    
    function collectManagementFee() external {
        _collectManagementFee();
    }
    
    function getReserves() external view returns (uint256, uint256) {
        return (reserve0, reserve1);
    }
    
    function getCFXPrice() external view returns (uint256) {
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        if (totalCFX == 0) return 0;
        
        uint256 price0 = IMultiTokenPriceOracle(priceOracle).getTokenPrice(token0);
        uint256 price1 = IMultiTokenPriceOracle(priceOracle).getTokenPrice(token1);
        
        uint8 dec0 = IERC20(token0).decimals();
        uint8 dec1 = IERC20(token1).decimals();
        
        uint256 val0 = _calcValue(reserve0, price0, dec0);
        uint256 val1 = _calcValue(reserve1, price1, dec1);
        
        return ((val0 + val1) * 1e18) / totalCFX;
    }
    
    function getUserValue(address user) external view returns (uint256, uint256, uint256) {
        uint256 userCFX = ICFXToken(cfxToken).balanceOf(user);
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        
        if (totalCFX == 0) return (0, 0, 0);
        
        uint256 amt0 = (userCFX * reserve0) / totalCFX;
        uint256 amt1 = (userCFX * reserve1) / totalCFX;
        
        uint256 price0 = IMultiTokenPriceOracle(priceOracle).getTokenPrice(token0);
        uint256 price1 = IMultiTokenPriceOracle(priceOracle).getTokenPrice(token1);
        
        uint8 dec0 = IERC20(token0).decimals();
        uint8 dec1 = IERC20(token1).decimals();
        
        uint256 val0 = _calcValue(amt0, price0, dec0);
        uint256 val1 = _calcValue(amt1, price1, dec1);
        
        return (amt0, amt1, val0 + val1);
    }
    
    function estimateDeposit(uint256 amount0, uint256 amount1) 
        external view returns (uint256 cfxOut, bool validRatio) 
    {
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        
        if (totalCFX == 0) {
            uint256 liq = _sqrt(amount0 * amount1);
            cfxOut = liq > MIN_LIQUIDITY ? liq - MIN_LIQUIDITY : 0;
            validRatio = true;
        } else {
            uint256 req1 = (amount0 * reserve1) / reserve0;
            uint256 diff = req1 > amount1 ? req1 - amount1 : amount1 - req1;
            validRatio = diff * BASIS_POINTS <= req1 * RATIO_TOLERANCE;
            
            uint256 cfx0 = (amount0 * totalCFX) / reserve0;
            uint256 cfx1 = (amount1 * totalCFX) / reserve1;
            uint256 before = cfx0 < cfx1 ? cfx0 : cfx1;
            cfxOut = (before * (BASIS_POINTS - depositFee)) / BASIS_POINTS;
        }
    }
    
    function estimateWithdrawal(uint256 cfxAmount) external view returns (uint256, uint256) {
        uint256 totalCFX = ICFXToken(cfxToken).totalSupply();
        if (totalCFX == 0) return (0, 0);
        
        uint256 amt0 = (cfxAmount * reserve0) / totalCFX;
        uint256 amt1 = (cfxAmount * reserve1) / totalCFX;
        
        amt0 = (amt0 * (BASIS_POINTS - withdrawFee)) / BASIS_POINTS;
        amt1 = (amt1 * (BASIS_POINTS - withdrawFee)) / BASIS_POINTS;
        
        return (amt0, amt1);
    }
    
    function _calcValue(uint256 amt, uint256 price, uint8 dec) internal pure returns (uint256) {
        uint256 norm = dec <= 18 ? amt * 10**(18 - dec) : amt / 10**(dec - 18);
        return (norm * price) / 1e18;
    }
    
    function _sqrt(uint256 x) internal pure returns (uint256) {
        if (x == 0) return 0;
        uint256 z = (x + 1) / 2;
        uint256 y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
        return y;
    }
    
    // Admin functions
    function pause() external onlyOwner {
        paused = true;
    }
    
    function unpause() external onlyOwner {
        paused = false;
    }
    
    function setFees(uint256 _deposit, uint256 _withdraw, uint256 _mgmt) external onlyOwner {
        require(_deposit <= 100 && _withdraw <= 100 && _mgmt <= 300, "Fee too high");
        depositFee = _deposit;
        withdrawFee = _withdraw;
        managementFee = _mgmt;
    }
    
    function setFeeCollector(address _collector) external onlyOwner {
        require(_collector != address(0), "Invalid collector");
        feeCollector = _collector;
    }
    
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Invalid owner");
        owner = newOwner;
    }
}
